insert into public.imams (id, slug, name, short_name, role, email, bio, focus, sort) values
  ('22222222-2222-4222-8222-222222222222', 'amir-koshin', 'Sheikh Amir Koshin', 'Sh. Amir Koshin', 'Khateeb & Lecturer', '', 'Sheikh Amir Koshin is a khateeb and lecturer at the Islamic Center of Tucson. He delivers khutbahs in the Friday rotation, leads the weekday Qur''an memorization circles and the early-week hadith reminders on the Five Pillars of Islam, and teaches the weekend adult Islamic studies class.', array['Qur''an memorization','Hadith','Adult Islamic studies']::text[], 2),
  ('11111111-1111-4111-8111-111111111111', 'burhan-hamdan', 'Sheikh Burhan Hamdan', 'Sh. Burhan Hamdan', 'Director of Islamic Affairs', 'bhamdan@ictucson.org', 'Sheikh Burhan Hamdan serves as the Director of Islamic Affairs at the Islamic Center of Tucson. He leads most of the Friday khutbahs, teaches the evening reminders and the weekend youth and sisters'' programs, and holds office hours for anyone in the community who would like to talk.', array['Aqeedah','Tafsir','Names of Allah','Youth programs','Arabic']::text[], 1);
