insert into public.ayat (ref, ar, en, sort) values
  ('Al-Baqarah 2:286', 'لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا', 'Allah does not burden a soul beyond that it can bear.', 0),
  ('Ash-Sharh 94:5–6', 'فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا ۝ إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', 'For indeed, with hardship comes ease. Indeed, with hardship comes ease.', 1),
  ('Ar-Ra''d 13:28', 'أَلَا بِذِكْرِ ٱللَّهِ تَطْمَئِنُّ ٱلْقُلُوبُ', 'Surely, in the remembrance of Allah do hearts find rest.', 2),
  ('Al-Baqarah 2:152', 'فَٱذْكُرُونِىٓ أَذْكُرْكُمْ', 'So remember Me; I will remember you.', 3),
  ('Al-Baqarah 2:186', 'وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ', 'And when My servants ask you concerning Me, indeed I am near.', 4),
  ('At-Talaq 65:3', 'وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥ', 'And whoever relies upon Allah, then He is sufficient for him.', 5),
  ('Az-Zumar 39:53', 'لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ', 'Do not despair of the mercy of Allah.', 6),
  ('Ta-Ha 20:114', 'رَّبِّ زِدْنِى عِلْمًا', 'My Lord, increase me in knowledge.', 7),
  ('Al-Hujurat 49:13', 'إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ', 'Indeed, the most noble of you in the sight of Allah is the most righteous of you.', 8),
  ('Ash-Sharh 94:8', 'وَإِلَىٰ رَبِّكَ فَٱرْغَب', 'And to your Lord direct your longing.', 9);
insert into public.books (title, author, category, level, why, starter, sort) values
  ('The Qur''an: Saheeh International Translation', 'Saheeh International', 'Start here', 'Beginner', 'A clear, faithful English translation of the meanings.', true, 1),
  ('Fortress of the Muslim (Hisn al-Muslim)', 'Sa''id ibn Wahf al-Qahtani', 'Start here', 'Beginner', 'Pocket collection of authentic daily du''as and adhkar.', true, 2),
  ('The Three Fundamental Principles', 'Muhammad ibn ''Abd al-Wahhab', 'Belief', 'Beginner', 'Who is your Lord, what is your religion, who is your Prophet? The core text taught in the Monday class.', false, 3),
  ('The Sealed Nectar (Ar-Raheeq al-Makhtum)', 'Safiur Rahman al-Mubarakpuri', 'Prophetic biography', 'Beginner', 'An award-winning, readable biography of the Prophet ﷺ from birth to his passing.', true, 4),
  ('Muhammad: His Life Based on the Earliest Sources', 'Martin Lings', 'Prophetic biography', 'Intermediate', 'Beautifully written narrative of the seerah drawn from the classical sources.', false, 5),
  ('The Forty Hadith (al-Arba''in)', 'Imam Yahya an-Nawawi', 'Hadith', 'Beginner', 'Forty-two foundational narrations that summarise the religion. Studied in the Sunday sisters'' program.', true, 6),
  ('Riyad as-Salihin (Gardens of the Righteous)', 'Imam Yahya an-Nawawi', 'Hadith', 'Intermediate', 'The classic collection on character and practice.', false, 7),
  ('Tafsir Ibn Kathir (Abridged)', 'Imam Ibn Kathir', 'Qur’an & Tafsir', 'Intermediate', 'The most widely read classical commentary, abridged and translated. A companion to the Sunday tafsir.', false, 8),
  ('The Disease and the Cure (ad-Da'' wa''d-Dawa'')', 'Ibn Qayyim al-Jawziyyah', 'Spirituality', 'Intermediate', 'A physician of the heart on sin, repentance, du''a and returning to Allah.', false, 9),
  ('Don''t Be Sad (La Tahzan)', '''Aid al-Qarni', 'Spirituality', 'Beginner', 'Short, hopeful reflections for anxious and hurting hearts, rooted in Qur''an and Sunnah.', false, 10),
  ('Al-''Aqidah al-Wasitiyyah', 'Ibn Taymiyyah', 'Belief', 'Advanced', 'A concise creed on the Names and Attributes of Allah. Pairs with the Saturday Names of Allah series.', false, 11),
  ('The Ideal Muslim & The Ideal Muslimah', 'Muhammad ''Ali al-Hashimi', 'Family & youth', 'Beginner', 'Good character with family, neighbours and society.', false, 12);
